# Physical constants used by the model regardless of Physics module
 
p0 = 1e5 # Pressure normalization factor for PhysicsState (Pa)
grav = 9.81 # Gravitational acceleration (m/s/s)


stephan_boltzmann_const = 5.67e-8
solar_const = 1367.0

atm_column_mass = 1e4   # Mass of entire atmosphere column per unit area (kg / m^2)
atm_cp = 1004.0 # Specific heat at constant pressure (J/K/kg)

ocn_rho = 1025.0  # Seawater density (kg/m^3)
ocn_cp = 3985.0   # Seawater specific heat capacity (J/kg/K)